fn deduplicate[T: Eq + Hash + Clone](items: &Vec[T]) -> Vec[T] {
  var seen = Set[T]();
  var result = Vec[T]();
  for item in items {
    if !seen.contains(item) {
      seen.insert(item.clone());
      result.push(item.clone());
    }
  }
  return result;
}

fn main() -> Int {
  let v = Vec[Int]();
  v.push(1); v.push(2); v.push(2); v.push(3); v.push(3); v.push(3); v.push(1);
  let d = deduplicate[Int](&v);
  return d.len();
}
